import {api,escape,requestId} from './workspace-shared.js';
import {createLessonQuiz} from './lesson-quiz.js';
export function createResourceLibrary({root,getClassId,onBusy=()=>{}}){
  root.innerHTML=`<h4>Course resources</h4><p>Upload the book or chapter excerpts, your unit plan, and supporting material. These files are shared with OpenAI for this course’s quiz drafts and remain available until you remove them. Students and parents cannot access these source files.</p><div data-resource-list></div><div class="planner-grid"><label>Resource type<select data-resource-kind><option value="book">Book / chapter excerpt</option><option value="unit-plan">Unit plan</option><option value="resource">Other teaching resource</option></select></label><label>Choose resources<input data-resource-files type="file" multiple accept=".pdf,.doc,.docx,.csv,.xls,.xlsx,.txt,.vtt"></label></div><p class="planner-hint">PDF, Word, CSV, Excel, TXT or VTT · 20 MiB per file · up to 8 files / 40 MiB per course. Excel and CSV: only the first 1,000 rows per sheet are read. Use smaller chapter excerpts for large books. Word and spreadsheet images are not read; use PDF for diagrams or scans.</p><button type="button" class="teacher-button secondary" data-resource-upload>Upload resources</button><p data-resource-status role="status"></p>`;
  const $=s=>root.querySelector(s);let busy=false,epoch=0,available=false;
  const render=data=>{available=data.available;$('[data-resource-list]').innerHTML=data.resources.length?`<ul class="course-resource-list">${data.resources.map(r=>`<li><div><strong>${escape(r.filename)}</strong><small>${escape(r.kind==='unit-plan'?'Unit plan':r.kind==='book'?'Book / chapter excerpt':'Teaching resource')} · ${r.bytes<1024?r.bytes+' bytes':(r.bytes/1024).toFixed(0)+' KiB'}</small></div><button type="button" class="text-button danger-text" data-remove-resource="${escape(r.id)}" aria-label="Remove ${escape(r.filename)}">Remove</button></li>`).join('')}</ul>`:'<p class="planner-hint">No resources uploaded yet.</p>';$('[data-resource-upload]').disabled=!available;};
  async function run(work){if(busy)return;busy=true;onBusy(true);const version=epoch,controls=[...root.querySelectorAll('button,input,select')],disabled=controls.map(c=>c.disabled);controls.forEach(c=>c.disabled=true);try{await work(version);}catch(e){if(version===epoch)$('[data-resource-status]').textContent=e.message;}finally{if(version===epoch){busy=false;onBusy(false);controls.forEach((c,i)=>c.disabled=disabled[i]);$('[data-resource-upload]').disabled=!available;}}}
  $('[data-resource-upload]').onclick=()=>run(async version=>{
    const files=[...$('[data-resource-files]').files];if(!files.length)throw Error('Choose at least one resource.');if(files.length>8 || files.some(f=>!f.size || f.size>20*1024*1024))throw Error('Choose up to 8 files, each 20 MiB or smaller.');
    const id=getClassId(),kind=$('[data-resource-kind]').value;
    for(const file of files){$('[data-resource-status]').textContent='Uploading '+file.name+'…';const body=new FormData();body.append('kind',kind);body.append('file',file);const result=await api(`/api/course-resources/classes/${id}`,body,{timeoutMs:110000});if(version!==epoch)return;render(result);}
    $('[data-resource-files]').value='';$('[data-resource-status]').textContent='Resources ready. Draft questions below, then review the answer keys before assigning.';
  });
  root.addEventListener('click',event=>{const button=event.target.closest('[data-remove-resource]');if(!button || busy)return;if(!confirm('Remove this resource from the course and OpenAI? Saved quiz drafts and assigned quizzes will remain.'))return;run(async version=>{const result=await api(`/api/course-resources/classes/${getClassId()}`,{action:'remove',id:button.dataset.removeResource},{timeoutMs:30000});if(version===epoch){render(result);$('[data-resource-status]').textContent='Resource removed.';}});});
  return {isBusy:()=>busy,reset(){epoch++;busy=false;onBusy(false);$('[data-resource-files]').value='';$('[data-resource-list]').replaceChildren();},async load(){const version=++epoch;$('[data-resource-status]').textContent='Loading course resources…';try{const result=await api(`/api/course-resources/classes/${getClassId()}`);if(version!==epoch)return;render(result);$('[data-resource-status]').textContent=available?'':'OpenAI is not connected.';}catch(e){if(version===epoch)$('[data-resource-status]').textContent=e.message;}}};
}
export function createCourseQuizSetup({root,getClassId,canGenerate}){
  root.classList.add('course-quiz-setup');root.innerHTML=`<details class="planner-source"><summary>Resources &amp; AI quizzes</summary><div data-course-library></div><h4>Draft pre-lesson quizzes</h4><p>Use your saved lesson topics, reading assignments and uploaded resources to draft quizzes for the course. Each draft is private until you review it and choose Save &amp; assign quiz.</p><label>Questions per quiz<select data-course-question-count>${[3,5,8,10].map(n=>`<option ${n===5?'selected':''}>${n}</option>`).join('')}</select></label><label>Quiz brief or pasted source text<textarea data-course-quiz-brief rows="3" maxlength="3000" placeholder="For example: a short reading check using the chapters assigned for each lesson, suitable for Grade 5."></textarea></label><button type="button" class="teacher-button secondary" data-course-quiz-generate>Draft quizzes for course</button><p data-course-quiz-status role="status"></p><div data-course-quiz-drafts></div></details>`;
  const $=s=>root.querySelector(s),library=createResourceLibrary({root:$('[data-course-library]'),getClassId});let busy=false,epoch=0,state=null;
  const render=()=>{$('[data-course-quiz-drafts]').innerHTML=(state?.lessons || []).filter(l=>l.hasDraft).map(l=>`<p class="course-quiz-draft"><span>Lesson ${l.number} · ${escape(l.title)}</span><button type="button" class="text-button" data-review-course-quiz="${escape(l.id)}">Review AI draft</button></p>`).join('');};
  const refresh=async()=>{const version=epoch,id=getClassId();const result=await api(`/api/quiz-assistant/classes/${id}`);if(version!==epoch)return;state=result;render();};
  $('[data-course-quiz-generate]').onclick=async()=>{
    if(busy || library.isBusy())return;if(!canGenerate()){$('[data-course-quiz-status]').textContent='Save your course overview before drafting quizzes.';return;}
    busy=true;const version=epoch,controls=[...root.querySelectorAll('button,input,select,textarea')],disabled=controls.map(c=>c.disabled);controls.forEach(c=>c.disabled=true);
    try{
      await refresh();if(version!==epoch)return;if(!state.available)throw Error('OpenAI is not connected.');
      const ids=state.lessons.filter(l=>!l.cancelled && !l.assigned && !l.hasDraft).map(l=>l.id),id=getClassId(),questionCount=Number($('[data-course-question-count]').value),brief=$('[data-course-quiz-brief]').value;
      if(!ids.length)throw Error('Every scheduled lesson already has a quiz or draft. Review a draft below, or open a lesson on the timeline to generate a replacement.');
      let saved=0,skipped=0;
      for(let i=0;i<ids.length;i+=5){
        $('[data-course-quiz-status]').textContent=`Drafting quizzes ${i+1}–${Math.min(i+5,ids.length)} of ${ids.length}… Each batch may take up to 2½ minutes.`;
        const result=await api(`/api/quiz-assistant/classes/${id}`,{requestId:requestId(),courseRevision:state.courseRevision,lessonIds:ids.slice(i,i+5),questionCount,brief},{timeoutMs:155000});if(version!==epoch)return;
        saved+=result.saved.length;skipped+=result.skipped.length;await refresh();
      }
      $('[data-course-quiz-status]').textContent=`${saved} quiz drafts ready for review.${skipped?' '+skipped+' lessons need more source material or changed during generation. Open those lessons to try again.':''}`;
      document.dispatchEvent(new CustomEvent('inkwire:quiz-changed',{detail:{classId:id}}));
    }catch(e){if(version===epoch){$('[data-course-quiz-status]').textContent=e.message+' Any completed drafts are saved; refresh or try again to continue.';try{await refresh();}catch{}}}
    finally{if(version===epoch){busy=false;controls.forEach((c,i)=>c.disabled=disabled[i]);}}
  };
  root.addEventListener('click',event=>{const button=event.target.closest('[data-review-course-quiz]');if(button && !busy && !library.isBusy())createLessonQuiz().open(getClassId(),button.dataset.reviewCourseQuiz,button);});
  document.addEventListener('inkwire:quiz-changed',event=>{if(event.detail.classId===getClassId() && !busy)refresh().catch(()=>{});});
  return {isBusy:()=>busy || library.isBusy(),reset(){epoch++;busy=false;state=null;library.reset();render();},async load(){epoch++;$('[data-course-quiz-status]').textContent='';await Promise.all([library.load(),refresh().catch(e=>{$('[data-course-quiz-status]').textContent=e.message;})]);}};
}
